143	
144		task := createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)
145		if task.ID != 1 || task.Status != "pending" || task.DurationSeconds != 30 || task.Attempts != 0 {
146			t.Fatalf("unexpected task: %+v", task)
147		}
148		if task.CreatedAt.IsZero() || task.NextClaimableAt.IsZero() {
149			t.Fatalf("task times not set: %+v", task)
