173	func TestTaskClaimAndReportSuccess(t *testing.T) {
174		store, clock := newClockStore()
175		h := NewHandler(store)
176		mustRegister(t, h, "dev-1")
177		createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)
178	
