180		if claim.Attempt != 1 || claim.Credential == "" {
181			t.Fatalf("unexpected claim: %+v", claim)
182		}
183		if !claim.Deadline.Equal(clock.UTC().Add(30 * time.Second)) {
184			t.Fatalf("deadline = %s, want %s", claim.Deadline, clock.UTC().Add(30*time.Second))
185		}
186		if claim.Task.Status != "in_progress" || claim.Task.Attempts != 1 {
187			t.Fatalf("claim task state: %+v", claim.Task)
188		}
189	
190		// One task in progress at a time.
191		claimTask(t, h, "dev-1", http.StatusNoContent)
192	
193		// Report success.
194		report := reportTask(t, h, "dev-1", claim.Task.ID,
195			reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true,"value":42}`), http.StatusCreated)
196		if !report.Success || report.ReceiptID != "rcpt-1" {
197			t.Fatalf("unexpected report: %+v", report)
198		}
199	
200		task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
201		if task.Status != "succeeded" || task.Result == nil || task.CompletedAt == nil {
202			t.Fatalf("task after success: %+v", task)
203		}
204	
205		// Same receiptId, same content -> 200 with the first result.
206		reportTask(t, h, "dev-1", claim.Task.ID,
207			reportBody("rcpt-1", claim.Credential, true, "", `{"value":42,"ok":true}`), http.StatusOK)
208		// Same receiptId, different content -> 409.
209		reportTask(t, h, "dev-1", claim.Task.ID,
210			reportBody("rcpt-1", claim.Credential, true, "", `{"ok":false}`), http.StatusConflict)
211		// Same receiptId, numeric value compared by value -> 200.
212		reportTask(t, h, "dev-1", claim.Task.ID,
213			reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true,"value":42.0}`), http.StatusOK)
214		// Same receiptId, array order is significant -> 409.
215		reportTask(t, h, "dev-1", claim.Task.ID,
216			reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true,"value":[1,2]}`), http.StatusConflict)
217	
218		// A new receiptId with a stale credential -> 409.
219		reportTask(t, h, "dev-1", claim.Task.ID,
220			reportBody("rcpt-2", claim.Credential, true, "", `{"ok":true}`), http.StatusConflict)
221	}
