	after := decodeBody[struct {
		LastSeenAt time.Time `json:"lastSeenAt"`
	}](t, doRequest(t, h, http.MethodGet, "/v1/fleet", "")).LastSeenAt
	if !after.Equal(before) {
		t.Fatalf("device activity time changed: %s -> %s", before, after)
	}
	_ = clock
}

